/**
 * Maryland Crab-Pot Regulation Boundaries + Natural Oyster Bars
 *
 * Two regulatory fishing/crabbing layers from MD DNR. These are NOT fishing
 * SPOTS — they are regulation-boundary overlays the app draws on the Fish
 * Map so a user can immediately see which rules apply at their location.
 *
 * ── Crab-Pot Boundaries ──
 * Source: MD DNR ArcGIS — Crab_Pot_Regulations_2024_view/FeatureServer/0
 *   https://services.arcgis.com/njFNhDsUCentVYJW/ArcGIS/rest/services
 *   312 demarcation POINTS. Each is a landmark that defines the corner
 *   of a crab-pot regulation zone (per COMAR 08.02.03.07). Regions:
 *     LES (Lower Eastern Shore)     = 137
 *     LWS (Lower Western Shore)     =  65
 *     POT (Potomac)                 =  51
 *     UWS (Upper Western Shore)     =  31
 *     UES (Upper Eastern Shore)     =  28
 *   Consecutive COMAR references within a region chain up to describe the
 *   actual boundary. The app renders these as numbered pins plus a tap-
 *   sheet with the COMAR ref.
 *
 * ── Natural Oyster Bars (NOBs) ──
 * Source: MD DNR ArcGIS — Maryland_Natural_Oyster_Bars_(NOBs)/FeatureServer/0
 *   381 POLYGON features describing state-designated Natural Oyster Bars.
 *   These are protected oyster grounds regulated by COMAR 08.02.04.
 *   Polygons were Douglas-Peucker simplified at 20 m tolerance during
 *   ingest (63,879 → 7,128 vertices, 11.2% retained). 17 ring(s)
 *   would have collapsed below 4 points under that tolerance, so the
 *   original unsimplified ring was retained to keep the polygon valid.
 *   Coordinates are [lng, lat], rings are closed (first == last).
 *
 * Last updated: 2026-04-19 (ingest)
 */

export interface CrabPotBoundaryPoint {
  /** Stable id derived from DNR OBJECTID. */
  id: string;
  /** Landmark name, e.g. "Rocky Point". */
  pointName: string;
  /** COMAR regulation reference, e.g. "08.02.03.07F(1)(a)". */
  comarReference: string;
  /** DNR region code. */
  region: 'LES' | 'LWS' | 'POT' | 'UWS' | 'UES';
  /** Named waterbody, e.g. "Susquehanna Flats". */
  waterbody: string;
  lat: number;
  lng: number;
}

export interface NaturalOysterBar {
  /** Stable id derived from DNR FID. */
  id: string;
  /** NOB name, e.g. "NOB 1-1". Suffix like "(2)" appended when DNR has
   *  duplicate NOB_NAME entries across features. */
  name: string;
  /** Polygon rings, outer-first. Each ring is [lng, lat] pairs, closed. */
  rings: [number, number][][];
}

